query:
-- Deletar todos os usuários exceto o admin (openId = 'admin')
DELETE FROM users WHERE openId != 'admin';

-- Deletar memberships órfãs
DELETE FROM memberships WHERE userId NOT IN (SELECT id FROM users);

-- Deletar estudos órfãos
DELETE FROM studies WHERE createdBy NOT IN (SELECT id FROM users);

-- Deletar comentários órfãos
DELETE FROM studyComments WHERE authorId NOT IN (SELECT id FROM users);

-- Deletar arquivos órfãos
DELETE FROM studyFiles WHERE uploadedBy NOT IN (SELECT id FROM users);

-- Deletar consultas rápidas órfãs
DELETE FROM quickQueries WHERE userId NOT IN (SELECT id FROM users);

-- Deletar logs de auditoria
DELETE FROM auditLogs;

-- Listar usuários restantes
SELECT id, openId, name, email FROM users;

